package gc

import (
	"fmt"
	"unsafe"
)

// NativeABIVersion identifies the checked collector metadata layout consumed by
// generated code. Artifact loading and instantiation must validate it before
// publishing the basedata pointer; generated operations then trust that immutable
// contract while reloading every mutable backing pointer/count they consume. The
// view is refreshed in place whenever growable backing can relocate, and callers
// must still serialize access with collector mutation.
// Version 8 also gates the dead-reservation/native-preparation helper dispatch.
const NativeABIVersion uint32 = 9

// Native allocation-stat offsets are relative to the AllocationCount pointer
// in NativeCollectorView. Generated AMD64 dead charges use these counters to
// invalidate pending-object accounting after a collection without adding work
// to ordinary allocation or collection paths.
const (
	NativeAllocationMinorCollectionsOffset = 8
	NativeAllocationFullCollectionsOffset  = 16
	NativeAllocationDeadObjectsOffset      = 56
)

// Native handle-entry layout. These constants are part of NativeABIVersion and
// are verified against handleEntry below.
const (
	NativeHandleStride                = 16
	NativeHandleOffsetOffset          = 0
	NativeHandleSizeOffset            = 4
	NativeHandleCardSlotOffset        = 8
	NativeHandleMetadataOffset        = 12
	NativeHandleSpaceOffset           = 14
	NativeHandleRememberedOffset      = 15
	NativeSpaceFree              byte = byte(spaceFree)
	NativeSpaceNursery           byte = byte(spaceNursery)
	NativeSpaceOld               byte = byte(spaceOld)
	NativeSpaceLarge             byte = byte(spaceLarge)
	NativeSpaceTiny              byte = byte(spaceTiny)
	NativeSpaceCount                  = 5
	NativeObjectCardStride            = 16
	NativeObjectCardHandleOffset      = 0
	NativeObjectCardStartOffset       = 4
	NativeObjectCardEndOffset         = 8
	NativeObjectCardNextOffset        = 12
)

// NativeSpaceView names one collector heap backing. Space zero deliberately
// remains empty so a handle's native space byte indexes this array directly.
type NativeSpaceView struct {
	Base  uintptr
	Bytes uint32
	_     uint32
}

// NativeCollectorView is a stable, versioned descriptor for the collector's
// relocatable handle table and fixed heap spaces. The Collector owns this object
// for its complete lifetime, so generated code may cache only the view pointer;

package gc

import (
	"errors"
	"fmt"
	"unsafe"
)

// ObjHeader is the stable guest-object header stored in the byte heap before
// every payload. It is represented here for layout documentation/tests; heap
// memory stores the fields little-endian, not as Go heap objects.
type ObjHeader struct {
	TypeID uint32
	Size   uint32 // total object size including header
	Aux    uint32 // array length, or forwarding metadata during copying
	Flags  uint32 // generation/color/age/pointer-free/forwarding bits
}

const (
	FlagPointerFree uint32 = 1 << iota
	FlagForwarded
	FlagMarked
	FlagOld
	FlagLarge
)

const HeaderSize = uint32(unsafe.Sizeof(ObjHeader{}))
const PayloadOffset = HeaderSize

// ErrAllocationTooLarge reports an object whose physical aligned extent cannot
// be represented by the collector's uint32 heap ABI.
var ErrAllocationTooLarge = errors.New("gc: allocation size too large")

func Align8(v uint32) uint32  { return align(v, 8) }
func Align16(v uint32) uint32 { return align(v, 16) }

func makeAlignedBytes(size uint32, alignment uintptr) []byte {
	if size == 0 {
		return nil
	}
	raw := make([]byte, uint64(size)+uint64(alignment-1))
	base := uintptr(unsafe.Pointer(&raw[0]))
	delta := (alignment - base%alignment) % alignment
	start := int(delta)
	end := start + int(size)
	return raw[start:end:end]
}

func requiredObjectAlignment(types []TypeDesc) uint32 {
	alignment := uint32(8)
	for _, d := range types {
		if (d.Kind == KindStruct || d.Kind == KindArray) && d.Align > alignment {
			alignment = d.Align
		}
	}
	return alignment
}
func StructSize(d TypeDesc) (uint32, error) {
	if d.Kind != KindStruct {
		return 0, fmt.Errorf("gc: type %d is not a struct", d.ID)
	}
	total := uint64(HeaderSize) + uint64(d.Size)
	if total > uint64(^uint32(0)-7) {
		return 0, fmt.Errorf("gc: struct size overflow: %w", ErrAllocationTooLarge)
	}
	return Align8(uint32(total)), nil
}
func ArraySize(d TypeDesc, length uint32) (uint32, error) {
	if d.Kind != KindArray {
		return 0, fmt.Errorf("gc: type %d is not an array", d.ID)
	}
	payload := uint64(d.ElemSize) * uint64(length)
	total := uint64(HeaderSize) + payload
	if total > uint64(^uint32(0)-7) {
		return 0, fmt.Errorf("gc: array size overflow: %w", ErrAllocationTooLarge)
	}
	return Align8(uint32(total)), nil
}

